<div class="form-grid">
<div class="form-group"><label for="student_id">Book ID</label><input id="id" name="id" maxlength="30" required></div>
<div class="form-group"><label for="email">Title</label><input id="title" name="title" required></div>
<div class="form-group"><label for="first_name">Author</label><input id="author" name="author" maxlength="100" required></div>
<div class="form-group"><label for="last_name">Genre</label><input id="genre" name="genre" maxlength="100" required></div>
<div class="form-group"><label for="course">Year Published</label><input id="year_published" name="year_published" maxlength="100" required></div>